-- public.channel_audience definition

-- Per-channel audience counters, one row per (channel, dim, bucket): dim 'msgs' = histogram
-- of each chatter's message count (1..20 exact, then ranges; audience = sum, one-time =
-- bucket '1', core = buckets from 100 up, median from the histogram), 'badge' = highest
-- membership badge (max_member_status: -1 never a member, 0 new, then months; 'none'
-- unknown), 'stay' = first-to-last-message span buckets, 'mod' / 'yes' = ever moderators.

-- Drop table

-- DROP TABLE public.channel_audience;

CREATE TABLE public.channel_audience (
	channel_id text NOT NULL,
	dim text NOT NULL,
	bucket text NOT NULL,
	n int8 NOT NULL,
	CONSTRAINT channel_audience_pkey PRIMARY KEY (channel_id, dim, bucket)
);


-- public.channel_audience_monthly definition

-- Per channel and month: arrivals = chatters whose first message on the channel was that
-- month; last_seen = chatters whose latest message on it is in that month (departures,
-- once the month is old enough that they'd likely have come back). regulars / active =
-- chatters who were regulars / chatted that month (from active_weeks). returning /
-- reg_returning = active (regular) this month AND the month before. Retention mix: new =
-- channel_retention age 0; back after a break = active - new - returning.

-- Drop table

-- DROP TABLE public.channel_audience_monthly;

CREATE TABLE public.channel_audience_monthly (
	channel_id text NOT NULL,
	month date NOT NULL,
	arrivals int8 DEFAULT 0 NOT NULL,
	last_seen int8 DEFAULT 0 NOT NULL,
	regulars int8 DEFAULT 0 NOT NULL,
	active int8 DEFAULT 0 NOT NULL,
	returning int8 DEFAULT 0 NOT NULL,
	reg_returning int8 DEFAULT 0 NOT NULL,
	CONSTRAINT channel_audience_monthly_pkey PRIMARY KEY (channel_id, month)
);


-- public.channel_audience_yearly definition

-- Per channel and year: regulars (chatted in each of 4 consecutive weeks, with that run
-- touching the year -- see user_channel_activity.active_weeks) and active chatters (any
-- chat that year). Distinct people per year, so NOT the sum of channel_audience_monthly's
-- regulars/active columns (which count per month the same way).

-- Drop table

-- DROP TABLE public.channel_audience_yearly;

CREATE TABLE public.channel_audience_yearly (
	channel_id text NOT NULL,
	year int4 NOT NULL,
	regulars int8 DEFAULT 0 NOT NULL,
	active int8 DEFAULT 0 NOT NULL,
	CONSTRAINT channel_audience_yearly_pkey PRIMARY KEY (channel_id, year)
);


-- public.channel_top_chatters definition

-- Each channel's top 100 chatters by message count (exact: totals only grow, so a chatter
-- can only enter by reaching the current #100, which is all the ingest path stages). Join
-- user_channel_activity on its primary key and user_ids for details -- 100 key lookups.

-- Drop table

-- DROP TABLE public.channel_top_chatters;

CREATE TABLE public.channel_top_chatters (
	channel_id text NOT NULL,
	user_id text NOT NULL,
	total_messages int8 NOT NULL,
	CONSTRAINT channel_top_chatters_pkey PRIMARY KEY (channel_id, user_id)
);


