-- public.channel_overlap definition

-- Chatters shared by each pair of channels (Community overlap). channel_a < channel_b in
-- byte order (COLLATE "C") -- the same order Python's sorted() and DuckDB use.

-- Drop table

-- DROP TABLE public.channel_overlap;

CREATE TABLE public.channel_overlap (
	channel_a text NOT NULL,
	channel_b text NOT NULL,
	shared int8 NOT NULL,
	CONSTRAINT channel_overlap_pkey PRIMARY KEY (channel_a, channel_b),
	CONSTRAINT channel_overlap_order CHECK (((channel_a COLLATE "C") < (channel_b COLLATE "C")))
);


-- public.regular_overlap definition

-- Chatters who were regulars of BOTH channels in the same year; year 0 = in at least one
-- common year. Unlike channel_overlap (anyone who ever chatted on both), this leaves out
-- one-off collab visitors and people who followed the two talents years apart.
-- channel_a < channel_b in byte order (COLLATE "C").

-- Drop table

-- DROP TABLE public.regular_overlap;

CREATE TABLE public.regular_overlap (
	channel_a text NOT NULL,
	channel_b text NOT NULL,
	year int4 NOT NULL,
	shared int8 NOT NULL,
	CONSTRAINT regular_overlap_pkey PRIMARY KEY (channel_a, channel_b, year),
	CONSTRAINT regular_overlap_order CHECK (((channel_a COLLATE "C") < (channel_b COLLATE "C")))
);


-- public.scope_regulars definition

-- Distinct regulars per scope ('group:<b>/<g>', 'branch:<b>', 'company', 'official') and
-- year: regular of at least one of the scope's channels that year. Year 0 = ever.

-- Drop table

-- DROP TABLE public.scope_regulars;

CREATE TABLE public.scope_regulars (
	scope text NOT NULL,
	year int4 NOT NULL,
	n int8 NOT NULL,
	CONSTRAINT scope_regulars_pkey PRIMARY KEY (scope, year)
);


-- public.channel_retention definition

-- Cohort retention per channel. kind 'A': cohort = the chatter's first active month there,
-- n = how many of that cohort chatted again `age` months later (age 0 = the cohort itself;
-- classic retention, so a cohort can dip and recover). kind 'R': the same with regular
-- months (cohort = first month as a regular). Months follow active_weeks (a week belongs
-- to the month of its Monday). % retained = n / (n at age 0). Delta-maintained:
-- audience_retention_delta -> FoldAudience.

-- Drop table

-- DROP TABLE public.channel_retention;

CREATE TABLE public.channel_retention (
	channel_id text NOT NULL,
	kind bpchar(1) NOT NULL,
	cohort date NOT NULL,
	age int2 NOT NULL,
	n int8 DEFAULT 0 NOT NULL,
	CONSTRAINT channel_retention_pkey PRIMARY KEY (channel_id, kind, cohort, age),
	CONSTRAINT channel_retention_kind_check CHECK ((kind = ANY (ARRAY['A'::bpchar, 'R'::bpchar])))
);


-- public.scope_retention definition

-- channel_retention for DISTINCT chatters of a scope ('group:<b>/<g>', 'branch:<b>',
-- 'company', 'official'): active (or regular) in a month = on ANY of its channels. Kept by
-- FoldAudience from audience_activity_change, which reads the changed users' other
-- user_channel_activity rows (Database.SCOPE_RETENTION switches that off). The scope's
-- returning mix is in scope_audience_monthly.

-- Drop table

-- DROP TABLE public.scope_retention;

CREATE TABLE public.scope_retention (
	scope text NOT NULL,
	kind bpchar(1) NOT NULL,
	cohort date NOT NULL,
	age int2 NOT NULL,
	n int8 DEFAULT 0 NOT NULL,
	CONSTRAINT scope_retention_pkey PRIMARY KEY (scope, kind, cohort, age),
	CONSTRAINT scope_retention_kind_check CHECK ((kind = ANY (ARRAY['A'::bpchar, 'R'::bpchar])))
);


